package com.kidsvideo.app;

import android.app.*;import android.graphics.Color;import android.os.Bundle;import android.view.*;import android.webkit.*;import android.widget.*;import java.util.Random;

public class PlayerActivity extends Activity {
 private Prefs prefs;private WebView web;private EnglishSpeaker speaker;private SpeechHelper speech;private TimeLimit limit;private String title;private int qIndex=0;
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=new Prefs(this);speech=new SpeechHelper(this);speaker=new EnglishSpeaker(this,prefs.voiceLocale());limit=new TimeLimit(this);String id=getIntent().getStringExtra("id");title=getIntent().getStringExtra("title");LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.BLACK);web=new WebView(this);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setMediaPlaybackRequiresUserGesture(false);s.setUserAgentString(s.getUserAgentString()+" KidsVideo/1.0");web.setBackgroundColor(Color.BLACK);web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){String u=r.getUrl().toString();return !(u.contains("youtube.com/embed/")||u.contains("youtube-nocookie.com/embed/"));}});String html="<html><body style='margin:0;background:#000'><iframe width='100%' height='100%' src='https://www.youtube-nocookie.com/embed/"+id+"?autoplay=1&playsinline=1&rel=0' frameborder='0' allow='autoplay; encrypted-media; picture-in-picture' allowfullscreen></iframe></body></html>";web.loadDataWithBaseURL("https://www.youtube-nocookie.com",html,"text/html","UTF-8",null);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(Ui.dp(this,8),Ui.dp(this,4),Ui.dp(this,8),Ui.dp(this,4));Button back=new Button(this);back.setText("← Back");back.setOnClickListener(v->finish());bar.addView(back);TextView tt=new TextView(this);tt.setText(title==null?"":title);tt.setTextColor(Color.WHITE);tt.setTextSize(16);tt.setMaxLines(2);bar.addView(tt,new LinearLayout.LayoutParams(0,-2,1));Button fav=new Button(this);fav.setText(prefs.isFavorite(id)?"★":"☆");fav.setOnClickListener(v->{prefs.toggleFavorite(id);fav.setText(prefs.isFavorite(id)?"★":"☆");});bar.addView(fav);Button talk=new Button(this);talk.setText("🎤 Talk in English");talk.setAllCaps(false);talk.setOnClickListener(v->conversation());bar.addView(talk);root.addView(bar);setContentView(root);limit.start();}
 private void conversation(){String[]qs=AppConfig.conversationQuestions(title);String q=qs[qIndex++%qs.length];speaker.speak(q);new AlertDialog.Builder(this).setTitle("Speak in English").setMessage(q).setPositiveButton("Answer",(d,w)->{speech.listen(prefs.voiceLocale(),new SpeechHelper.Callback(){public void onResult(String text){runOnUiThread(()->{String reply=AppConfig.isDaughter()?"Great speaking! I heard: "+text+". Can you tell me one more thing?":"Good explanation. I heard: "+text+". Try adding one reason or example next time.";speaker.speak(reply);new AlertDialog.Builder(PlayerActivity.this).setTitle("Nice English!").setMessage(reply).setPositiveButton("OK",null).show();});}public void onError(String m){runOnUiThread(()->Toast.makeText(PlayerActivity.this,m,Toast.LENGTH_LONG).show());}});}).setNegativeButton("Later",null).show();}
 @Override protected void onPause(){super.onPause();limit.stop();if(web!=null)web.onPause();}
 @Override protected void onResume(){super.onResume();limit.start();if(web!=null)web.onResume();}
 @Override protected void onDestroy(){super.onDestroy();limit.stop();if(speaker!=null)speaker.shutdown();if(speech!=null)speech.destroy();if(web!=null){web.loadUrl("about:blank");web.destroy();}}
}
